// Parse Tally webhook - body is either nested under .body or root level
const input = $input.first().json;
const body = input.body || input;
const fields = body?.data?.fields || [];

const fieldMap = {};
for (const field of fields) {
  const key = (field.label || '')
    .toLowerCase().trim()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_|_$/g, '');
  const val = (() => {
    if (field.options && field.options.length > 0) {
      const ids = Array.isArray(field.value) ? field.value : [field.value];
      return ids
        .map(id => {
          const opt = field.options.find(o => o.id === id);
          return opt ? opt.text : id;
        })
        .filter(Boolean)
        .join(', ');
    }
    return Array.isArray(field.value)
      ? field.value.filter(Boolean).join(', ')
      : String(field.value ?? '');
  })();
  if (key) fieldMap[key] = val;
  if (field.type === 'INPUT_EMAIL' && !fieldMap.email) fieldMap.email = val;
  if (field.type === 'INPUT_PHONE_NUMBER' && !fieldMap.phone) fieldMap.phone = val;
}

const lead = {
  name:          fieldMap.full_name      || fieldMap.name           || fieldMap.your_name    || fieldMap.first_name    || '',
  email:         fieldMap.email          || fieldMap.email_address   || fieldMap.your_email   || '',
  phone:         fieldMap.phone          || fieldMap.phone_number    || fieldMap.your_phone   || fieldMap.mobile        || '',
  company:       fieldMap.company        || fieldMap.company_name    || fieldMap.business     || fieldMap.organisation  || '',
  message:       fieldMap.message        || fieldMap.your_message    || fieldMap.how_can_we_help || fieldMap.inquiry    || fieldMap.tell_us_more || fieldMap.problem_description || fieldMap.any_message || Object.entries(fieldMap).find(([k]) => k.includes('message'))?.[1] || '',
  budget:        fieldMap.budget         || fieldMap.your_budget     || fieldMap.monthly_budget || '',
  service_type:  fieldMap.service_type   || fieldMap.service         || fieldMap.service_interest || fieldMap.type_of_service || '',
  property_type: fieldMap.property_type  || fieldMap.property        || '',
  urgency:       fieldMap.urgency        || fieldMap.urgency_level   || fieldMap.timeline      || '',
  location:      fieldMap.location       || fieldMap.zip_code        || fieldMap.location_zip_code || fieldMap.city || fieldMap.address || '',
  source:        'tally_form',
  submittedAt:   body?.data?.submittedAt || new Date().toISOString(),
  responseId:    body?.data?.responseId  || '',
  _rawFields:    fields,
};

lead.firstName = lead.name.split(' ')[0] || 'there';

// NORMALIZATION: Email lowercase + trim, Phone digits only
lead.email = (lead.email || '').toLowerCase().trim();
lead.phone = (lead.phone || '').replace(/\D/g, '');

return [{ json: lead }];

const claudeOut = $input.first().json;
const lead = $('Normalize Lead Data').first().json;

const rawText = claudeOut.text ||
  (Array.isArray(claudeOut.content) ? claudeOut.content.map(b => b.text || '').join('') : '') ||
  JSON.stringify(claudeOut);

let parsed = {};
try {
  const jsonMatch = rawText.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : rawText);
} catch (e) {
  parsed = {
    score: 'warm',
    score_reason: 'AI response could not be parsed - defaulting to warm',
    email_subject: 'Thanks for reaching out',
    email_body: `Hi ${lead.firstName},\n\nThank you for your message! We have received your inquiry and will be in touch within 24 hours.\n\nBest regards`,
    follow_up_priority: 'medium',
    key_signals: ['parse_error']
  };
}

return [{ json: { ...lead, ...parsed } }];

